initial_condition:
with {
    the SUT being in the "initial state" and
    the SUT containing an initial Entity ${entity} 
        with an id set to ${entityId} 
        and an attribute with an id set to ${atrId}
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Partial Update Entity Attributes with Response Status Code set to 204     and
        Retrieve Entity by Id with Check Updated Entity and
            Query Parameter: 'ignored_keys' set to '${None}'
}
